mapper.select:
select a.id as id, a.case_id as caseId, a.case_title as caseTitle, a.user_name as userName, a.pay_money as payMoney, a.pay_name as payName, a.account_name as accountName, a.bank_name as bankName, a.card_no as cardNo, a.pay_state as payState, a.create_time as createTime, a.pay_time as payTime, a.operator_name as operatorName, a.img as img, a.audit_state as auditState, a.audit_reason as auditReason, a.remarks as remarks from case_pay_info a left join case_center_info cci on a.case_id = cci.id where a.pay_money is not null
and a.user_name like CONCAT(CONCAT('%',#{userName,jdbcType=VARCHAR}), '%')
and a.case_title like CONCAT(CONCAT('%',#{caseTitle,jdbcType=VARCHAR}), '%')
and a.pay_state = #{payState,jdbcType=INTEGER}
and a.audit_state = #{auditState,jdbcType=INTEGER}
and a.audit_state in (1,2,3,4)
and a.audit_state = 2
and cci.is_test_case = #{isTestcase,jdbcType=INTEGER}
and cci.is_test_case = 0
and cci.is_test_case = 1
and cci.delete_flag !=1 order by a.create_time desc limit #{pageIndex}, #{pageSize}
